        d = json.load(open(name))
        if isinstance(d, list):
            n = len(d)
            sc = sum(1 for x in d if x.get('sc_answer','') == x.get('gold_answer',''))
            sica = sum(1 for x in d if x.get('sica_answer','') == x.get('gold_answer',''))
            print(f'{name}: n={n}, SC={sc/n*100:.2f}%, SICA={sica/n*100:.2f}%, delta={((sica-sc)/n)*100:.2f}pp')
